import { Component, Element, Prop, h } from "@stencil/core";

/**
 * @since 0.0.13
 * @status stable
 *
 */

@Component({
	tag: "hbr-loader",
	styleUrl: "loader.scss",
	shadow: true,
})
export class Loader {
	maxSize = 60;
	@Element() host: HTMLHbrLoaderElement;

	// size of the loader, max size 60
	@Prop() size = 24;

	/** Attributes related to screen readers. */
	@Prop() aria: { label: string };

	render() {
		if (this.size > this.maxSize) this.size = this.maxSize;
		const width = Math.round(this.size * 2.5);
		const shapeWidth = Math.round(width * 0.047);
		return (
			<div
				part="base"
				class={{
					loader: true,
				}}
				aria-label={this.aria?.label || "Loading..."}
				role="status"
				aria-live="polite"
			>
				<div
					class="loading"
					style={{
						height: `${this.size}px`,
						width: `${width}px`,
					}}
				>
					{[...Array(9).keys()].map(() => (
						<div class="shape" style={{ width: `${shapeWidth}px` }} />
					))}
				</div>
				<div class="label">
					<slot />
				</div>
			</div>
		);
	}
}
